    // `pi-out-h`, with the orientation and the view applied. `smp` holds the samples (or `bm` the host's pixels when
    // `pi-adopt` was called); `have` 1 says `mi`, `msmp`, `mbm` are the mask's record, samples and pixels (a stencil
    // `/Mask` or an `/SMask`: `pi-info` on its object). `fill` is a stencil's colour, 0xRRGGBB. Answers 0, 1 for a
    // colour space that is not read, 2 when `out` or `alpha` is not the right size, 3 for an image with no size.
    let w: i32 = crate::port::cells_at(im, PI_W);
    let h: i32 = crate::port::cells_at(im, PI_H);
    let ow: i32 = pi_out_w(im);
    let oh: i32 = pi_out_h(im);
    let orient: i32 = crate::port::cells_at(im, PI_ORI);
    let ch: i32 = pi_out_channels(im);
    let matte: i32 = pi_matte_on(im, mi, have);
    let mut ox: i32 = 0;
    let mut oy: i32 = 0;
    let mut sx: i32 = 0;
    let mut sy: i32 = 0;
    let mut rgb: i32 = 0;
    let mut al: i32 = 0;
    let mut r: i32 = 0;
    let mut g: i32 = 0;
    let mut b: i32 = 0;
    if (w < 1) || (h < 1) {
        return 3;
    }
    if crate::port::cells_at(im, PI_CLASS) == 9 {
        return 1;
    }
    if (ow < 1) || (oh < 1) {
        return 3;
    }
    if (crate::port::bitmap_w(out) != ow) || ((crate::port::bitmap_h(out) != oh) || (crate::port::bitmap_channels(out) != ch)) {
        return 2;
    }
    if (crate::port::bitmap_w(alpha) != ow) || ((crate::port::bitmap_h(alpha) != oh) || (crate::port::bitmap_channels(alpha) != 1)) {
        return 2;
    }
